    readonly List<NetView> netViews=new List<NetView>();int lastNetTick=-1;float netMaxDeformation;int netVertexCount;readonly List<Mesh> netMeshes=new List<Mesh>();readonly List<Transform> actors=new List<Transform>();readonly List<Transform> rings=new List<Transform>();readonly List<PlayableGraph> graphs=new List<PlayableGraph>();readonly List<AnimationClipPlayable> playables=new List<AnimationClipPlayable>();
