    void FrameRendered(UnityEngine.Rendering.ScriptableRenderContext context,Camera[] cameras){var now=Time.realtimeSinceStartupAsDouble;if(lastRender>0){frameTimes.Enqueue((float)((now-lastRender)*1000));if(frameTimes.Count>7200)frameTimes.Dequeue();}lastRender=now;renderCount++;SendWorldProjection();}
