    #endif
    void Start(){Application.targetFrameRate=60;if(defaultScenario!=null)Load(JsonUtility.FromJson<Config>(defaultScenario.text));Send("ready");announced=true;}
    public void Command(string json){try{var c=JsonUtility.FromJson<CommandMessage>(json);requestId=c.id;switch(c.command){case "load":Load(c.config);break;case "start":case "resume":simulation.Start();break;case "pause":simulation.Pause();accumulator=0;break;case "reset":Load(simulation.Config);break;case "restore":simulation.Restore(ReadRestoreCheckpoint(json));BuildWorld();accumulator=0;break;case "checkpoint":simulation.Pause();accumulator=0;Send("checkpoint",simulation.Checkpoint());return;case "camera":simulation.State.cameraMode=c.config?.mode=="contact"?"contact":"overview";break;case "snapshot":case "stats":break;default:throw new ArgumentException("Unsupported command");}Render();Send("state");}catch(Exception e){Send("error",null,e.Message);}finally{requestId=null;}}
    // A single contract path avoids JsonUtility creating an empty alternate checkpoint.
    public static Checkpoint ReadRestoreCheckpoint(string json){return JsonUtility.FromJson<CommandMessage>(json)?.config?.checkpoint;}
    void Load(Config config){worldView=null;worldActors=null;simulation=new ProbeSimulation(config);accumulator=0;BuildWorld();Render();}
    void Update(){if(worldView!=null){RenderWorld();return;}if(simulation==null)return;bool wasRunning=simulation.State.running;if(wasRunning){accumulator+=Math.Min(Time.unscaledDeltaTime,0.1);int steps=0;while(accumulator>=ProbeSimulation.StepSeconds&&steps++<8){simulation.Step();accumulator-=ProbeSimulation.StepSeconds;}}ProbeCamera.Apply(Camera.main,simulation.Config.scenario,simulation.State.cameraMode,simulation.State.ball);Render();if(announced&&(Time.unscaledTime>=sendAt||wasRunning&&!simulation.State.running)){sendAt=Time.unscaledTime+.2f;Send("state");}}
    void Send(string type,Checkpoint checkpoint=null,string error=null){var json=JsonUtility.ToJson(new Envelope{id=requestId,type=type,state=simulation?.State,checkpoint=checkpoint,error=error,stats=new Stats{frameTimesMs=frameTimes.ToArray(),renderCount=renderCount,objects=actors.Count,contactPoses=contactPoses.ToArray(),netMaxDeformation=netMaxDeformation,netVertexCount=netVertexCount,allocatedBytes=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()}});
        #if UNITY_WEBGL && !UNITY_EDITOR
        D6ProbeSend(json);
        #else
        if(type=="error")Debug.LogError(json);
        #endif
    }
    static Vector3 V(double[] a){return new Vector3((float)a[0],(float)a[1],(float)a[2]);}
    void Clear(){ClearWorldPresentation();rigs.Clear();football.Clear();contactPoses.Clear();netViews.Clear();lastNetTick=-1;netMaxDeformation=0;netVertexCount=0;foreach(var g in graphs)if(g.IsValid())g.Destroy();graphs.Clear();playables.Clear();actors.Clear();rings.Clear();if(world!=null){world.gameObject.SetActive(false);Destroy(world.gameObject);}foreach(var mesh in netMeshes)Destroy(mesh);netMeshes.Clear();}
    readonly List<Material> materials=new List<Material>();
    Material Mat(Color c){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;materials.Add(m);return m;}
    Transform Box(string name,Vector3 position,Vector3 scale,Material material){var go=GameObject.CreatePrimitive(PrimitiveType.Cube);go.name=name;go.transform.SetParent(world,false);go.transform.position=position;go.transform.localScale=scale;go.GetComponent<Renderer>().sharedMaterial=material;Destroy(go.GetComponent<Collider>());return go.transform;}
    Transform Rod(string name,Vector3 position,float length,bool horizontal,Material material){var go=GameObject.CreatePrimitive(PrimitiveType.Cylinder);go.name=name;go.transform.SetParent(world,false);go.transform.position=position;go.transform.localScale=new Vector3(.12f,length/2,.12f);if(horizontal)go.transform.rotation=Quaternion.Euler(90,0,0);go.GetComponent<Renderer>().sharedMaterial=material;Destroy(go.GetComponent<Collider>());return go.transform;}
    void GoalNet(float x,float back,float width,float height,Material material){
        var vertices=new List<Vector3>();var triangles=new List<int>();var tags=new List<string>();string panelTag="back";
        void Segment(Vector3 a,Vector3 b,Vector3 normal){var offset=Vector3.Cross(b-a,normal).normalized*.0125f;int n=vertices.Count;vertices.Add(a+offset);vertices.Add(a-offset);vertices.Add(b-offset);vertices.Add(b+offset);triangles.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});for(int i=0;i<4;i++)tags.Add(panelTag);}
        void Strand(Vector3 a,Vector3 b,Vector3 normal){int steps=Mathf.CeilToInt((b-a).magnitude/.25f);for(int n=0;n<steps;n++)Segment(Vector3.Lerp(a,b,n/(float)steps),Vector3.Lerp(a,b,(n+1)/(float)steps),normal);}
        void Panel(Vector3 origin,Vector3 u,Vector3 v,Vector3 normal,string tag){panelTag=tag;int nu=Mathf.CeilToInt(u.magnitude/.35f),nv=Mathf.CeilToInt(v.magnitude/.35f);for(int i=0;i<=nu;i++)Strand(origin+u*(i/(float)nu),origin+u*(i/(float)nu)+v,normal);for(int i=0;i<=nv;i++)Strand(origin+v*(i/(float)nv),origin+v*(i/(float)nv)+u,normal);}
        Panel(new Vector3(back,0,-width/2),new Vector3(0,0,width),new Vector3(0,height,0),Vector3.right,"back");Panel(new Vector3(x,height,-width/2),new Vector3(back-x,0,0),new Vector3(0,0,width),Vector3.up,"roof");foreach(int side in new[]{-1,1})Panel(new Vector3(x,0,side*width/2),new Vector3(back-x,0,0),new Vector3(0,height,0),Vector3.forward,side<0?"left":"right");
        var mesh=new Mesh{name="Goal net mesh"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.MarkDynamic();netMeshes.Add(mesh);netViews.Add(new NetView{mesh=mesh,rest=vertices.ToArray(),vertices=vertices.ToArray(),tags=tags.ToArray(),goalSign=Math.Sign(x)});material.SetFloat("_Cull",0);var net=new GameObject("Goal net",typeof(MeshFilter),typeof(MeshRenderer));net.transform.SetParent(world,false);net.GetComponent<MeshFilter>().sharedMesh=mesh;net.GetComponent<MeshRenderer>().sharedMaterial=material;
        foreach(int side in new[]{-1,1}){Box("Net support",new Vector3(back,height/2,side*width/2),new Vector3(.065f,height,.065f),material);Box("Net roof support",new Vector3((x+back)/2,height,side*width/2),new Vector3(Mathf.Abs(back-x),.065f,.065f),material);}Box("Rear crossbar",new Vector3(back,height,0),new Vector3(.065f,.065f,width),material);
    }
    void BuildWorld(){Clear();foreach(var m in materials)Destroy(m);materials.Clear();world=new GameObject("ProbeWorld").transform;kitMaterials.Clear();liveNetMoved=false;var g=worldView?.Config.geometry??simulation.Config.scenario.geometry;var length=(float)g.length;var width=(float)g.width;var line=Mat(new Color(.92f,.94f,.85f));var grassA=Mat(new Color(87/255f,148/255f,80/255f));var grassB=Mat(new Color(75/255f,132/255f,71/255f));
        for(int i=0;i<12;i++)Box("Grass",new Vector3(-length/2+(i+.5f)*length/12,-.06f,0),new Vector3(length/12,.1f,width),i%2==0?grassA:grassB);
        foreach(int sign in new[]{-1,1}){Box("Touchline",new Vector3(0,.005f,sign*width/2),new Vector3(length,.018f,.10f),line);Box("Goal line",new Vector3(sign*length/2,.005f,0),new Vector3(.10f,.018f,width),line);float x=sign*(length/2-(float)g.penaltyDepth);Box("Box front",new Vector3(x,.008f,0),new Vector3(.10f,.018f,(float)g.penaltyWidth),line);foreach(int side in new[]{-1,1}){Box("Box side",new Vector3(sign*(length/2-(float)g.penaltyDepth/2),.008f,side*(float)g.penaltyWidth/2),new Vector3((float)g.penaltyDepth,.018f,.10f),line);Rod("Goal post",new Vector3(sign*length/2,(float)g.goalHeight/2,side*(float)g.goalWidth/2),(float)g.goalHeight,false,line);}Rod("Crossbar",new Vector3(sign*length/2,(float)g.goalHeight,0),(float)g.goalWidth,true,line);}
        Box("Halfway",new Vector3(0,.008f,0),new Vector3(.10f,.018f,width),line);
        var netMaterial=Mat(new Color(.79f,.84f,.81f));foreach(int sign in new[]{-1,1})GoalNet(sign*length/2,sign*(length/2+2.2f),(float)g.goalWidth,(float)g.goalHeight,netMaterial);
        var ball=GameObject.CreatePrimitive(PrimitiveType.Sphere);ball.name="Ball";ball.transform.SetParent(world,false);ball.transform.localScale=Vector3.one*(worldView!=null?.1764f:(float)simulation.State.ball.radius)*2;ball.GetComponent<Renderer>().sharedMaterial=line;Destroy(ball.GetComponent<Collider>());ballView=ball.transform;
        var shadow=GameObject.CreatePrimitive(PrimitiveType.Cylinder);shadow.name="Ball ground reference";shadow.transform.SetParent(world,false);shadow.transform.localScale=new Vector3(.4f,.004f,.4f);shadow.GetComponent<Renderer>().sharedMaterial=Mat(new Color(.1f,.22f,.15f));Destroy(shadow.GetComponent<Collider>());ballShadow=shadow.transform;
        var team0=Mat(new Color(241/255f,189/255f,90/255f));var team1=Mat(new Color(103/255f,211/255f,209/255f));int count=worldView!=null?worldActors.Length:Math.Max((g.fieldPlayers+1)*2,simulation.State.actors.Length);for(int i=0;i<count;i++){var go=Instantiate(playerPrefab,world);go.name=worldView!=null?worldActors[i].id:i<simulation.State.actors.Length?simulation.State.actors[i].id:"Display reserve "+i;WorldMesh(go);go.transform.localScale=Vector3.one*1.45f;foreach(var r in go.GetComponentsInChildren<Renderer>()){r.sharedMaterial=WorldMaterial(i);r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;}var animator=go.GetComponent<Animator>();if(animator==null)animator=go.AddComponent<Animator>();animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;var actor=BuildActor(i);var clip=actor!=null&&(Math.Abs(actor.velocity[0])+Math.Abs(actor.velocity[2])>.01)?runClip:actor?.role=="keeper"?keeperClip:idleClip;var graph=PlayableGraph.Create("D6 clip "+i);graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var playable=AnimationClipPlayable.Create(graph,clip);var output=AnimationPlayableOutput.Create(graph,"Character",animator);output.SetSourcePlayable(playable);graph.Play();graph.Evaluate(0);if(worldView!=null||simulation.State.playProbe)football.Add(new FootballAnimation(graph,go.transform,FootballClips()));graphs.Add(graph);playables.Add(playable);actors.Add(go.transform);rigs.Add(new ProbePose.Rig(go.transform));var ring=GameObject.CreatePrimitive(PrimitiveType.Cylinder);ring.name="Team disc";ring.transform.SetParent(world,false);ring.transform.localScale=new Vector3(1.1f,.008f,1.1f);ring.GetComponent<Renderer>().sharedMaterial=(actor?.team??i%2)==0?team0:team1;Destroy(ring.GetComponent<Collider>());rings.Add(ring.transform);}
    }
    void RenderNets(State state){if(lastNetTick==state.tick)return;bool moving=false;foreach(var patch in state.netPatches)if(Math.Abs(patch.displacement)>.00001){moving=true;break;}if(lastNetTick>=0&&!moving&&netMaxDeformation==0){lastNetTick=state.tick;return;}lastNetTick=state.tick;netMaxDeformation=0;netVertexCount=0;foreach(var view in netViews){netVertexCount+=view.rest.Length;Array.Copy(view.rest,view.vertices,view.rest.Length);foreach(var patch in state.netPatches){if(patch.goalSign!=view.goalSign||Math.Abs(patch.displacement)<.00001)continue;int axis=patch.panel=="back"?0:patch.panel=="roof"?1:2,sign=patch.panel=="back"?patch.goalSign:patch.panel=="left"?-1:1;for(int i=0;i<view.rest.Length;i++){if(view.tags[i]!=patch.panel)continue;var p=view.rest[i];float d=(float)ProbeNet.Displacement(state.geometry,p.x,p.y,p.z,patch);var vertex=view.vertices[i];vertex[axis]+=sign*d;view.vertices[i]=vertex;netMaxDeformation=Mathf.Max(netMaxDeformation,Mathf.Abs(d));}}view.mesh.vertices=view.vertices;view.mesh.RecalculateNormals();view.mesh.RecalculateBounds();}}
    void Render(){if(simulation==null||world==null)return;ProbeCamera.Apply(Camera.main,simulation.Config.scenario,simulation.State.cameraMode,simulation.State.ball);var state=simulation.State;contactPoses.Clear();RenderNets(state);ballView.position=V(state.ball.position);ballShadow.position=new Vector3(ballView.position.x,.045f,ballView.position.z);for(int i=0;i<actors.Count;i++){var a=i<state.actors.Length?state.actors[i]:null;var pos=a!=null?V(a.position):new Vector3((i%7-3)*4,0,(i%2==0?-1:1)*(float)simulation.Config.scenario.geometry.width*.44f);pos.y=.08f;actors[i].position=pos;rings[i].position=new Vector3(pos.x,.02f,pos.z);Vector3 direction=a!=null?V(a.velocity):Vector3.right;if(state.playProbe)direction=V(a.facing);else if(direction.sqrMagnitude<.01)direction=ballView.position-pos;direction.y=0;if(direction.sqrMagnitude>.001)actors[i].rotation=Quaternion.LookRotation(direction);if(state.playProbe){RenderDemoFootball(i,a,state);continue;}var desired=a!=null&&(Math.Abs(a.velocity[0])+Math.Abs(a.velocity[2])>.01)?runClip:a?.role=="keeper"?keeperClip:idleClip;double sampleTime=state.elapsed+i*.09;bool oneShot=false;for(int e=state.events.Count-1;e>=0;e--){var evt=state.events[e];if(a==null||string.IsNullOrEmpty(evt.actorId)||evt.actorId!=a.id)continue;var age=state.elapsed-evt.time;if(evt.type=="shot-release"&&age>=0&&age<shotClip.length){desired=shotClip;sampleTime=age;oneShot=true;break;}if(evt.type=="contact"&&a.role=="keeper"&&age>=0&&age<keeperActionClip.length){desired=keeperActionClip;sampleTime=age;oneShot=true;break;}}ProbePose.Sample sample=default;if(state.playProbe){sample=ProbePose.Read(a,state);desired=sample.clip=="shot_meshy"?shotClip:sample.clip=="running"?runClip:sample.clip=="keeper_low_meshy"?keeperActionClip:sample.clip=="keeper_ready_meshy"?keeperClip:idleClip;sampleTime=sample.time;oneShot=sample.clip=="shot_meshy"||sample.clip=="keeper_low_meshy";}
        if(playables[i].GetAnimationClip()!=desired){graphs[i].DestroyPlayable(playables[i]);var p=AnimationClipPlayable.Create(graphs[i],desired);graphs[i].GetOutput(0).SetSourcePlayable(p);playables[i]=p;}var clip=playables[i];clip.SetTime(oneShot?Math.Min(sampleTime,desired.length):sampleTime%desired.length);graphs[i].Evaluate(0);if(state.playProbe&&sample.active){var actual=ProbePose.Solve(rigs[i],sample.point,sample.kind);var target=V(sample.point);contactPoses.Add(new ContactPose{id=a.id,kind=sample.kind,target=sample.point,actual=new[]{(double)actual.x,actual.y,actual.z},error=Vector3.Distance(actual,target),clip=sample.clip,time=sample.time});}}}
    void OnApplicationFocus(bool focus){if(!focus&&simulation!=null){simulation.Pause();accumulator=0;Send("state");}}
    void OnDestroy(){Clear();foreach(var m in materials)Destroy(m);}
}
